{"command":"cat > bw_test.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdint.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static size_t N = 64 * 1024 * 1024;

typedef struct { unsigned char *a, *b; size_t n; } job;

void *copy_job(void *p) {
    job *j = p;
    memcpy(j->b, j->a, j->n);
    return NULL;
}

void *read_job(void *p) {
    job *j = p;
    volatile unsigned long sum = 0;
    unsigned long *a = (unsigned long *)j->a;
    size_t n = j->n / 8;
    for (size_t i = 0; i < n; i++) sum += a[i];
    // prevent opt
    if (sum == 0xdead) printf("x");
    return NULL;
}

int main() {
    unsigned char *a = aligned_alloc(64, N);
    unsigned char *b = aligned_alloc(64, N);
    memset(a, 1, N);
    memset(b, 2, N);

    // single thread copy
    double t0 = now();
    int reps = 20;
    for (int i = 0; i < reps; i++) memcpy(b, a, N);
    double t1 = now();
    printf("memcpy 1thr 64MB x%d: %.3f s  %.1f GB/s (copy)\n", reps, t1-t0, (reps * 64.0 / 1024) / (t1-t0) * 2);

    // multi thread copy
    int nthreads = 6;
    size_t chunk = N / nthreads;
    pthread_t th[16];
    job jobs[16];
    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < nthreads; i++) {
            jobs[i].a = a + i * chunk;
            jobs[i].b = b + i * chunk;
            jobs[i].n = chunk;
            pthread_create(&th[i], NULL, copy_job, &jobs[i]);
        }
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("memcpy %dthr 64MB x%d: %.3f s  %.1f GB/s (copy, both ways)\n", nthreads, reps, t1-t0, (reps * 64.0 / 1024) / (t1-t0) * 2);

    // read bandwidth
    t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < nthreads; i++) {
            jobs[i].a = a + i * chunk;
            jobs[i].n = chunk;
            pthread_create(&th[i], NULL, read_job, &jobs[i]);
        }
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("read %dthr 64MB x%d: %.3f s  %.1f GB/s\n", nthreads, reps, t1-t0, (reps * 64.0 / 1024) / (t1-t0));

    // thread create overhead
    t0 = now();
    int n = 1000;
    for (int r = 0; r < n; r++) {
        for (int i = 0; i < nthreads; i++) pthread_create(&th[i], NULL, copy_job, &jobs[i]);
        for (int i = 0; i < nthreads; i++) pthread_join(th[i], NULL);
    }
    t1 = now();
    printf("thread create+join %d thr x%d: %.1f us each batch\n", nthreads, n, (t1-t0)/n*1e6);
    return 0;
}
EOF
