{"command":"cat > chacha_avx2.c << 'EOF'
/* AVX2 ChaCha20 (8 blocks parallel) + scalar Poly1305, RFC 8439 */
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static inline uint32_t load32(const uint8_t *p) {
    uint32_t v; memcpy(&v, p, 4); return v;
}
static inline void store32(uint8_t *p, uint32_t v) { memcpy(p, &v, 4); }
static inline uint64_t load64(const uint8_t *p) {
    uint64_t v; memcpy(&v, p, 8); return v;
}

#define ROTL(a,b) (((a) << (b)) | ((a) >> (32 - (b))))

/* quarter round on 8-wide vectors */
#define QR(a,b,c,d) do { \
    a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = _mm256_or_si256(_mm256_slli_epi32(d,16), _mm256_srli_epi32(d,16)); \
    c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = _mm256_or_si256(_mm256_slli_epi32(b,12), _mm256_srli_epi32(b,20)); \
    a = _mm256_add_epi32(a, b); d = _mm256_xor_si256(d, a); d = _mm256_or_si256(_mm256_slli_epi32(d, 8), _mm256_srli_epi32(d,24)); \
    c = _mm256_add_epi32(c, d); b = _mm256_xor_si256(b, c); b = _mm256_or_si256(_mm256_slli_epi32(b, 7), _mm256_srli_epi32(b,25)); \
} while (0)

/* Generate 8 blocks (512 bytes) of keystream starting at counter `counter`.
   out must be 512 bytes. key 32 bytes, nonce 12 bytes. */
static void chacha20_8blocks(const uint8_t key[32], const uint8_t nonce[12], uint32_t counter, uint8_t out[512]) {
    const uint32_t c0 = 0x61707865, c1 = 0x3320646e, c2 = 0x79622d32, c3 = 0x6b206574;
    uint32_t k0 = load32(key+0),  k1 = load32(key+4),  k2 = load32(key+8),  k3 = load32(key+12);
    uint32_t k4 = load32(key+16), k5 = load32(key+20), k6 = load32(key+24), k7 = load32(key+28);
    uint32_t n0 = load32(nonce+0), n1 = load32(nonce+4), n2 = load32(nonce+8);

    __m256i x0 = _mm256_set1_epi32(c0);
    __m256i x1 = _mm256_set1_epi32(c1);
    __m256i x2 = _mm256_set1_epi32(c2);
    __m256i x3 = _mm256_set1_epi32(c3);
    __m256i x4 = _mm256_set1_epi32(k0);
    __m256i x5 = _mm256_set1_epi32(k1);
    __m256i x6 = _mm256_set1_epi32(k2);
    __m256i x7 = _mm256_set1_epi32(k3);
    __m256i x8 = _mm256_set1_epi32(k4);
    __m256i x9 = _mm256_set1_epi32(k5);
    __m256i x10= _mm256_set1_epi32(k6);
    __m256i x11= _mm256_set1_epi32(k7);
    __m256i x12= _mm256_set_epi32(counter+7, counter+6, counter+5, counter+4,
                                  counter+3, counter+2, counter+1, counter+0);
    __m256i x13= _mm256_set1_epi32(n0);
    __m256i x14= _mm256_set1_epi32(n1);
    __m256i x15= _mm256_set1_epi32(n2);

    __m256i s0=x0,s1=x1,s2=x2,s3=x3,s4=x4,s5=x5,s6=x6,s7=x7;
    __m256i s8=x8,s9=x9,s10=x10,s11=x11,s12=x12,s13=x13,s14=x14,s15=x15;

    for (int i = 0; i < 10; i++) {
        /* column rounds */
        QR(x0,x4,x8,x12);
        QR(x1,x5,x9,x13);
        QR(x2,x6,x10,x14);
        QR(x3,x7,x11,x15);
        /* diagonal rounds: rotate rows b,c,d left by 1,2,3 within the 4-lane... 
           But lanes are independent blocks, so diagonal == column for this layout!
           Wait: each lane is a separate block. The "diagonal" round mixes
           words WITHIN a block, not across lanes. With set1 layout, words of
           one block are in the same lane of different vectors. Diagonal round
           is just QR on (x0, x5, x10, x15), (x1, x6, x11, x12), etc.
           No lane shuffle needed! */
        QR(x0,x5,x10,x15);
        QR(x1,x6,x11,x12);
        QR(x2,x7,x8,x13);
        QR(x3,x4,x9,x14);
    }

    x0 = _mm256_add_epi32(x0, s0);
    x1 = _mm256_add_epi32(x1, s1);
    x2 = _mm256_add_epi32(x2, s2);
    x3 = _mm256_add_epi32(x3, s3);
    x4 = _mm256_add_epi32(x4, s4);
    x5 = _mm256_add_epi32(x5, s5);
    x6 = _mm256_add_epi32(x6, s6);
    x7 = _mm256_add_epi32(x7, s7);
    x8 = _mm256_add_epi32(x8, s8);
    x9 = _mm256_add_epi32(x9, s9);
    x10= _mm256_add_epi32(x10, s10);
    x11= _mm256_add_epi32(x11, s11);
    x12= _mm256_add_epi32(x12, s12);
    x13= _mm256_add_epi32(x13, s13);
    x14= _mm256_add_epi32(x14, s14);
    x15= _mm256_add_epi32(x15, s15);

    /* Transpose lanes into sequential blocks.
       Each block is 16 uint32s. We want out[block*64 + word*4].
       Use extract + store per lane. 8*16 = 128 stores of 4 bytes is slow;
       better: store each vector then transpose 8x8? Simpler approach:
       extract 128-bit lanes and use a small scalar store of 32-bit words
       into the right place. For a first benchmark this is fine. */
    uint32_t tmp[16][8];
    _mm256_storeu_si256((__m256i*)tmp[0], x0);
    _mm256_storeu_si256((__m256i*)tmp[1], x1);
    _mm256_storeu_si256((__m256i*)tmp[2], x2);
    _mm256_storeu_si256((__m256i*)tmp[3], x3);
    _mm256_storeu_si256((__m256i*)tmp[4], x4);
    _mm256_storeu_si256((__m256i*)tmp[5], x5);
    _mm256_storeu_si256((__m256i*)tmp[6], x6);
    _mm256_storeu_si256((__m256i*)tmp[7], x7);
    _mm256_storeu_si256((__m256i*)tmp[8], x8);
    _mm256_storeu_si256((__m256i*)tmp[9], x9);
    _mm256_storeu_si256((__m256i*)tmp[10], x10);
    _mm256_storeu_si256((__m256i*)tmp[11], x11);
    _mm256_storeu_si256((__m256i*)tmp[12], x12);
    _mm256_storeu_si256((__m256i*)tmp[13], x13);
    _mm256_storeu_si256((__m256i*)tmp[14], x14);
    _mm256_storeu_si256((__m256i*)tmp[15], x15);

    for (int blk = 0; blk < 8; blk++) {
        uint32_t *dst = (uint32_t*)(out + blk * 64);
        for (int w = 0; w < 16; w++) dst[w] = tmp[w][blk];
    }
}

/* scalar one block for tail / verification */
static void chacha20_block(const uint32_t in[16], uint8_t out[64]) {
    uint32_t x[16];
    memcpy(x, in, 64);
    for (int i = 0; i < 10; i++) {
        #define Q(a,b,c,d) do { \
            x[a]+=x[b]; x[d]^=x[a]; x[d]=ROTL(x[d],16); \
            x[c]+=x[d]; x[b]^=x[c]; x[b]=ROTL(x[b],12); \
            x[a]+=x[b]; x[d]^=x[a]; x[d]=ROTL(x[d],8); \
            x[c]+=x[d]; x[b]^=x[c]; x[b]=ROTL(x[b],7); \
        } while(0)
        Q(0,4,8,12); Q(1,5,9,13); Q(2,6,10,14); Q(3,7,11,15);
        Q(0,5,10,15); Q(1,6,11,12); Q(2,7,8,13); Q(3,4,9,14);
        #undef Q
    }
    for (int i = 0; i < 16; i++) store32(out + 4*i, x[i] + in[i]);
}

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    uint8_t key[32], nonce[12];
    memset(key, 0x11, 32);
    memset(nonce, 0x22, 12);

    /* correctness vs scalar */
    uint32_t st[16] = {
        0x61707865,0x3320646e,0x79622d32,0x6b206574,
        load32(key),load32(key+4),load32(key+8),load32(key+12),
        load32(key+16),load32(key+20),load32(key+24),load32(key+28),
        0, load32(nonce), load32(nonce+4), load32(nonce+8)
    };
    uint8_t ref[64], got[512];
    chacha20_block(st, ref);
    chacha20_8blocks(key, nonce, 0, got);
    if (memcmp(ref, got, 64) != 0) {
        printf("MISMATCH block 0\n");
        for (int i = 0; i < 64; i++) printf("%02x", ref[i]); printf("\n");
        for (int i = 0; i < 64; i++) printf("%02x", got[i]); printf("\n");
        return 1;
    }
    st[12] = 7;
    chacha20_block(st, ref);
    if (memcmp(ref, got + 7*64, 64) != 0) {
        printf("MISMATCH block 7\n");
        return 1;
    }
    printf("correctness OK\n");

    size_t n = 40 * 1024 * 1024;
    uint8_t *out = aligned_alloc(64, n);
    double t0 = now();
    int reps = 10;
    for (int r = 0; r < reps; r++) {
        uint32_t counter = 0;
        for (size_t off = 0; off + 512 <= n; off += 512) {
            chacha20_8blocks(key, nonce, counter, out + off);
            counter += 8;
        }
    }
    double t1 = now();
    printf("avx2 8-block 40MB x%d: %.4f s  %.0f MB/s\n", reps, t1-t0, reps*40.0/(t1-t0));
    return 0;
}
EOF
cc -O3 -mavx2 -o chacha_avx2 chacha_avx2.c && ./chacha_avx2"}

