       We have 8 lanes. Do a 4x4 transpose on low 128 and high 128.
       After transpose of (w0,w1,w2,w3):
         low 128 of new_w0 = lanes 0 of w0,w1,w2,w3 = words word_base..+3 of block 0
       Use unpack. */
    __m256i t0 = _mm256_unpacklo_epi32(w0, w1); /* a0 b0 a1 b1 | a4 b4 a5 b5 */
    __m256i t1 = _mm256_unpackhi_epi32(w0, w1); /* a2 b2 a3 b3 | a6 b6 a7 b7 */
    __m256i t2 = _mm256_unpacklo_epi32(w2, w3);
    __m256i t3 = _mm256_unpackhi_epi32(w2, w3);
