    __m256i u1 = _mm256_unpackhi_epi64(t0, t2); /* a1 b1 c1 d1 | a5 ... */
    __m256i u2 = _mm256_unpacklo_epi64(t1, t3);
    __m256i u3 = _mm256_unpackhi_epi64(t1, t3);
