    /* u0 low = block0 words, u0 high = block4 words */
    _mm_storeu_si128((__m128i*)(out + 0*64 + word_base*4), _mm256_castsi256_si128(u0));
    _mm_storeu_si128((__m128i*)(out + 4*64 + word_base*4), _mm256_extracti128_si256(u0, 1));
