/* 128-bit accumulator mod 2^130-5 using __uint128_t, 3x44-bit limbs */
typedef struct {
    __uint128_t r;   /* clamped r, < 2^128 */
    __uint128_t h;   /* accumulator < 2^130 */
    uint64_t pad0, pad1;
} poly;

static void init(poly *p, const uint8_t key[32]) {
    uint64_t t0, t1;
    memcpy(&t0, key, 8); memcpy(&t1, key+8, 8);
    /* clamp r */
    t0 &= 0x0ffffffc0fffffffULL;
    t1 &= 0x0ffffffc0ffffffcULL;
    p->r = ((__uint128_t)t1 << 64) | t0;
