    if (full_hibit) n |= (__uint128_t)1 << 128;
    p->h += n;
    /* h * r mod 2^130-5 */
    /* 130-bit * 128-bit. Use schoolbook on 64-bit halves with care.
       h < 2^131 roughly (h + n). r < 2^124 after clamp actually < 2^124.
       Product < 2^255. Reduce mod 2^130-5: x = lo + hi * 2^130 = lo + hi*5  (since 2^130 = 5 mod p)
       where we split product into bits [0..129] and [130..]. */
    __uint128_t h = p->h;
    __uint128_t r = p->r;
    uint64_t h0 = (uint64_t)h;
    uint64_t h1 = (uint64_t)(h >> 64); /* up to ~67 bits */
    uint64_t r0 = (uint64_t)r;
    uint64_t r1 = (uint64_t)(r >> 64);
    /* product = (h0 + h1*2^64) * (r0 + r1*2^64)
       = h0*r0 + (h0*r1 + h1*r0)*2^64 + h1*r1*2^128 */
    __uint128_t p0 = (__uint128_t)h0 * r0;
    __uint128_t p1 = (__uint128_t)h0 * r1 + (__uint128_t)h1 * r0;
    __uint128_t p2 = (__uint128_t)h1 * r1;
    /* assemble into a 256-bit number: low 128 = p0 + (p1 << 64), carry into p2 */
    __uint128_t mid = (p1 << 64);
    __uint128_t low = p0 + mid;
    __uint128_t carry = (low < p0) ? 1 : 0;
    __uint128_t high = p2 + (p1 >> 64) + carry;
    /* now number = high * 2^128 + low. We want mod 2^130-5.
       = (high >> 2) * 2^130 + (low + (high & 3) * 2^128)
       = (high >> 2) * 5 + low + (high & 3) * 2^128   mod 2^130-5
       This result fits in ~132 bits, reduce again. */
    __uint128_t res = low + ((high & 3) << 128) + (high >> 2) * 5;
    /* res may be up to ~2^130 + a bit. Reduce once more. */
    __uint128_t hi2 = res >> 130;
    res = (res & (((__uint128_t)1 << 130) - 1)) + hi2 * 5;
    hi2 = res >> 130;
    res = (res & (((__uint128_t)1 << 130) - 1)) + hi2 * 5;
    p->h = res;
}

static void finish(poly *p, uint8_t tag[16]) {
    __uint128_t h = p->h;
