    __uint128_t hi = h >> 130;
    h = (h & (((__uint128_t)1 << 130) - 1)) + hi * 5;
    /* h < 2^130 + small. Compare with p = 2^130-5: if h >= p, subtract p */
    if (h >= (((__uint128_t)1 << 130) - 5)) h -= ((__uint128_t)1 << 130) - 5;
    /* now h < p, fits in 130 bits but actually < 2^130-5 so < 2^128? No, can be up to 2^130-6.
