    __uint128_t pad = ((__uint128_t)p->pad1 << 64) | p->pad0;
    __uint128_t t = (h & (((__uint128_t)1 << 128) - 1)) + pad; /* mod 2^128 addition, carry discarded — but only if h < 2^128!
