                 const uint8_t *pt, size_t pt_len, uint8_t *ct, uint8_t tag[16]) {
    uint8_t block0[64];
    chacha_block(key, nonce, 0, block0);
    poly_st poly; poly_init(&poly, block0);
    if (aad_len) {
        size_t full = aad_len & ~15ULL;
        if (full) poly_blocks(&poly, aad, full);
        if (aad_len & 15) {
            uint8_t tmp[16]={0}; memcpy(tmp, aad+full, aad_len&15); tmp[aad_len&15]=1;
            poly_block_hibit(&poly, tmp, 0);
        }
    }
    chacha_key ck; chacha_init(&ck, key, nonce);
    size_t off = 0;
    while (off + 512 <= pt_len) {
        chacha20_xor8(&ck, (uint32_t)(1 + off/64), pt+off, ct+off);
        off += 512;
    }
    if (off < pt_len) {
        size_t rem = pt_len - off;
        uint8_t ks[512];
        uint32_t counter = (uint32_t)(1 + off/64);
        size_t gen = 0;
        while (gen < rem) {
            chacha_block(key, nonce, counter++, ks+gen);
            gen += 64;
        }
        for (size_t i=0;i<rem;i++) ct[off+i] = pt[off+i] ^ ks[i];
    }
    size_t full = pt_len & ~15ULL;
    if (full) poly_blocks(&poly, ct, full);
    if (pt_len & 15) {
        uint8_t tmp[16]={0}; memcpy(tmp, ct+full, pt_len&15); tmp[pt_len&15]=1;
