    }
    uint8_t lens[16];
    uint64_t al=aad_len, pl=pt_len;
    memcpy(lens, &al, 8); memcpy(lens+8, &pl, 8);
    poly_block_hibit(&poly, lens, 1);
    poly_finish(&poly, tag);
}

