    CK.s6=_mm256_set1_epi32(ld32(key+8));  CK.s7=_mm256_set1_epi32(ld32(key+12));
    CK.s8=_mm256_set1_epi32(ld32(key+16)); CK.s9=_mm256_set1_epi32(ld32(key+20));
    CK.s10=_mm256_set1_epi32(ld32(key+24));CK.s11=_mm256_set1_epi32(ld32(key+28));
    CK.s13=_mm256_set1_epi32(ld32(nonce)); CK.s14=_mm256_set1_epi32(ld32(nonce+4));
    CK.s15=_mm256_set1_epi32(ld32(nonce+8));
}

static inline void store_xor(uint8_t *out, const uint8_t *in,
                             __m256i w0, __m256i w1, __m256i w2, __m256i w3, int wb) {
    __m256i t0=_mm256_unpacklo_epi32(w0,w1), t1=_mm256_unpackhi_epi32(w0,w1);
    __m256i t2=_mm256_unpacklo_epi32(w2,w3), t3=_mm256_unpackhi_epi32(w2,w3);
    __m256i u0=_mm256_unpacklo_epi64(t0,t2), u1=_mm256_unpackhi_epi64(t0,t2);
    __m256i u2=_mm256_unpacklo_epi64(t1,t3), u3=_mm256_unpackhi_epi64(t1,t3);
    #define XST(u,blk,hi) do { \
        __m128i ks = hi ? _mm256_extracti128_si256(u,1) : _mm256_castsi256_si128(u); \
        __m128i pt = _mm_loadu_si128((const __m128i*)(in + (blk)*64 + wb*4)); \
        _mm_storeu_si128((__m128i*)(out + (blk)*64 + wb*4), _mm_xor_si128(ks, pt)); \
    } while (0)
    XST(u0,0,0); XST(u0,4,1); XST(u1,1,0); XST(u1,5,1);
    XST(u2,2,0); XST(u2,6,1); XST(u3,3,0); XST(u3,7,1);
    #undef XST
}

static void chacha_xor8(uint32_t counter, const uint8_t *in, uint8_t *out) {
    __m256i x0=CK.s0,x1=CK.s1,x2=CK.s2,x3=CK.s3,x4=CK.s4,x5=CK.s5,x6=CK.s6,x7=CK.s7;
    __m256i x8=CK.s8,x9=CK.s9,x10=CK.s10,x11=CK.s11;
    __m256i x12=_mm256_set_epi32(counter+7,counter+6,counter+5,counter+4,
                                 counter+3,counter+2,counter+1,counter);
    __m256i x13=CK.s13, x14=CK.s14, x15=CK.s15, s12=x12;
    for (int i = 0; i < 10; i++) {
        QR(x0,x4,x8,x12); QR(x1,x5,x9,x13); QR(x2,x6,x10,x14); QR(x3,x7,x11,x15);
        QR(x0,x5,x10,x15); QR(x1,x6,x11,x12); QR(x2,x7,x8,x13); QR(x3,x4,x9,x14);
    }
    x0=_mm256_add_epi32(x0,CK.s0); x1=_mm256_add_epi32(x1,CK.s1);
    x2=_mm256_add_epi32(x2,CK.s2); x3=_mm256_add_epi32(x3,CK.s3);
    x4=_mm256_add_epi32(x4,CK.s4); x5=_mm256_add_epi32(x5,CK.s5);
    x6=_mm256_add_epi32(x6,CK.s6); x7=_mm256_add_epi32(x7,CK.s7);
    x8=_mm256_add_epi32(x8,CK.s8); x9=_mm256_add_epi32(x9,CK.s9);
    x10=_mm256_add_epi32(x10,CK.s10); x11=_mm256_add_epi32(x11,CK.s11);
    x12=_mm256_add_epi32(x12,s12); x13=_mm256_add_epi32(x13,CK.s13);
    x14=_mm256_add_epi32(x14,CK.s14); x15=_mm256_add_epi32(x15,CK.s15);
    store_xor(out, in, x0,x1,x2,x3, 0);
    store_xor(out, in, x4,x5,x6,x7, 4);
    store_xor(out, in, x8,x9,x10,x11, 8);
    store_xor(out, in, x12,x13,x14,x15, 12);
}

static void chacha_block(const uint8_t key[32], const uint8_t nonce[12], uint32_t counter, uint8_t out[64]) {
    uint32_t s[16] = {0x61707865,0x3320646e,0x79622d32,0x6b206574,
        ld32(key),ld32(key+4),ld32(key+8),ld32(key+12),
        ld32(key+16),ld32(key+20),ld32(key+24),ld32(key+28),
        counter, ld32(nonce), ld32(nonce+4), ld32(nonce+8)};
    uint32_t x[16]; memcpy(x, s, 64);
    for (int i = 0; i < 10; i++) {
        #define Q(a,b,c,d) do { x[a]+=x[b]; x[d]^=x[a]; x[d]=ROTL(x[d],16); \
            x[c]+=x[d]; x[b]^=x[c]; x[b]=ROTL(x[b],12); \
            x[a]+=x[b]; x[d]^=x[a]; x[d]=ROTL(x[d],8); \
            x[c]+=x[d]; x[b]^=x[c]; x[b]=ROTL(x[b],7);} while(0)
        Q(0,4,8,12); Q(1,5,9,13); Q(2,6,10,14); Q(3,7,11,15);
        Q(0,5,10,15); Q(1,6,11,12); Q(2,7,8,13); Q(3,4,9,14);
        #undef Q
    }
    for (int i = 0; i < 16; i++) st32(out+4*i, x[i]+s[i]);
}

/* ---------------- Poly1305, 4 parallel accumulators ---------------- */
typedef struct { uint32_t h[5]; } limb5;

typedef struct {
    uint32_t r[5];
    uint32_t rr[4][5];   /* r^1 .. r^4 */
    uint32_t s1[4], s2[4], s3[4], s4[4];
    uint32_t pad[4];
} poly_key;

static void limbs_from_block(uint32_t h[5], const uint8_t m[16], uint32_t hibit) {
    uint32_t t0=ld32(m), t1=ld32(m+4), t2=ld32(m+8), t3=ld32(m+12);
    h[0] = t0 & 0x3ffffff;
    h[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffffff;
    h[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffffff;
    h[3] = ((t2 >> 14) | (t3 << 18)) & 0x3ffffff;
    h[4] = (t3 >> 8) | (hibit << 24);
}

/* h = (h + m) * r, single block, r given as limbs plus precomputed 5*r[1..4] */
static void poly_mul(uint32_t h[5], const uint32_t r[5], uint32_t s1, uint32_t s2, uint32_t s3, uint32_t s4) {
    uint32_t h0=h[0], h1=h[1], h2=h[2], h3=h[3], h4=h[4];
    uint32_t r0=r[0], r1=r[1], r2=r[2], r3=r[3], r4=r[4];
    uint64_t d0=(uint64_t)h0*r0 + (uint64_t)h1*s4 + (uint64_t)h2*s3 + (uint64_t)h3*s2 + (uint64_t)h4*s1;
    uint64_t d1=(uint64_t)h0*r1 + (uint64_t)h1*r0 + (uint64_t)h2*s4 + (uint64_t)h3*s3 + (uint64_t)h4*s2;
    uint64_t d2=(uint64_t)h0*r2 + (uint64_t)h1*r1 + (uint64_t)h2*r0 + (uint64_t)h3*s4 + (uint64_t)h4*s3;
    uint64_t d3=(uint64_t)h0*r3 + (uint64_t)h1*r2 + (uint64_t)h2*r1 + (uint64_t)h3*r0 + (uint64_t)h4*s4;
    uint64_t d4=(uint64_t)h0*r4 + (uint64_t)h1*r3 + (uint64_t)h2*r2 + (uint64_t)h3*r1 + (uint64_t)h4*r0;
    uint64_t c;
    c=d0>>26; h0=(uint32_t)d0 & 0x3ffffff; d1+=c;
    c=d1>>26; h1=(uint32_t)d1 & 0x3ffffff; d2+=c;
    c=d2>>26; h2=(uint32_t)d2 & 0x3ffffff; d3+=c;
    c=d3>>26; h3=(uint32_t)d3 & 0x3ffffff; d4+=c;
    c=d4>>26; h4=(uint32_t)d4 & 0x3ffffff; h0+=(uint32_t)c*5;
    c=h0>>26; h0&=0x3ffffff; h1+=(uint32_t)c;
    h[0]=h0; h[1]=h1; h[2]=h2; h[3]=h3; h[4]=h4;
}

static void poly_block(uint32_t h[5], const uint8_t m[16], uint32_t hibit, const uint32_t r[5]) {
    uint32_t t[5]; limbs_from_block(t, m, hibit);
    h[0]+=t[0]; h[1]+=t[1]; h[2]+=t[2]; h[3]+=t[3]; h[4]+=t[4];
    poly_mul(h, r, r[1]*5, r[2]*5, r[3]*5, r[4]*5);
}

static void poly_key_init(poly_key *pk, const uint8_t key[32]) {
    uint32_t t0=ld32(key), t1=ld32(key+4), t2=ld32(key+8), t3=ld32(key+12);
    pk->r[0] = t0 & 0x3ffffff;
    pk->r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffff03;
    pk->r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffc0ff;
    pk->r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3f03fff;
    pk->r[4] = (t3 >> 8) & 0x00fffff;
    pk->pad[0]=ld32(key+16); pk->pad[1]=ld32(key+20);
    pk->pad[2]=ld32(key+24); pk->pad[3]=ld32(key+28);
    /* rr[0] = r^1, rr[i] = r^(i+1) */
    memcpy(pk->rr[0], pk->r, sizeof pk->r);
    for (int i = 1; i < 4; i++) {
        memcpy(pk->rr[i], pk->rr[i-1], sizeof pk->r);
        poly_mul(pk->rr[i], pk->r, pk->r[1]*5, pk->r[2]*5, pk->r[3]*5, pk->r[4]*5);
    }
    for (int i = 0; i < 4; i++) {
        pk->s1[i] = pk->rr[i][1]*5; pk->s2[i] = pk->rr[i][2]*5;
        pk->s3[i] = pk->rr[i][3]*5; pk->s4[i] = pk->rr[i][4]*5;
    }
}

/* Process len bytes (multiple of 64) with 4 parallel accumulators, each consuming
 * every 4th 16-byte block, multiplied by r^4 per step. */
static void poly_blocks4(const poly_key *pk, const uint8_t *m, size_t len, limb5 acc[4]) {
    const uint32_t *r4 = pk->rr[3];
    uint32_t s1=pk->s1[3], s2=pk->s2[3], s3=pk->s3[3], s4=pk->s4[3];
    uint32_t h0[4], h1[4], h2[4], h3[4], h4[4];
    for (int k=0;k<4;k++){ h0[k]=acc[k].h[0]; h1[k]=acc[k].h[1]; h2[k]=acc[k].h[2]; h3[k]=acc[k].h[3]; h4[k]=acc[k].h[4]; }
    size_t off = 0;
    while (off + 64 <= len) {
        for (int k = 0; k < 4; k++) {
            uint32_t t[5]; limbs_from_block(t, m+off+16*k, 1);
            uint32_t a0=h0[k]+t[0], a1=h1[k]+t[1], a2=h2[k]+t[2], a3=h3[k]+t[3], a4=h4[k]+t[4];
            uint32_t r0=r4[0], r1=r4[1], r2=r4[2], r3=r4[3], r4l=r4[4];
            uint64_t d0=(uint64_t)a0*r0 + (uint64_t)a1*s4 + (uint64_t)a2*s3 + (uint64_t)a3*s2 + (uint64_t)a4*s1;
            uint64_t d1=(uint64_t)a0*r1 + (uint64_t)a1*r0 + (uint64_t)a2*s4 + (uint64_t)a3*s3 + (uint64_t)a4*s2;
            uint64_t d2=(uint64_t)a0*r2 + (uint64_t)a1*r1 + (uint64_t)a2*r0 + (uint64_t)a3*s4 + (uint64_t)a4*s3;
            uint64_t d3=(uint64_t)a0*r3 + (uint64_t)a1*r2 + (uint64_t)a2*r1 + (uint64_t)a3*r0 + (uint64_t)a4*s4;
            uint64_t d4=(uint64_t)a0*r4l + (uint64_t)a1*r3 + (uint64_t)a2*r2 + (uint64_t)a3*r1 + (uint64_t)a4*r0;
            uint64_t c;
            c=d0>>26; a0=(uint32_t)d0 & 0x3ffffff; d1+=c;
            c=d1>>26; a1=(uint32_t)d1 & 0x3ffffff; d2+=c;
            c=d2>>26; a2=(uint32_t)d2 & 0x3ffffff; d3+=c;
            c=d3>>26; a3=(uint32_t)d3 & 0x3ffffff; d4+=c;
            c=d4>>26; a4=(uint32_t)d4 & 0x3ffffff; a0+=(uint32_t)c*5;
            c=a0>>26; a0&=0x3ffffff; a1+=(uint32_t)c;
            h0[k]=a0; h1[k]=a1; h2[k]=a2; h3[k]=a3; h4[k]=a4;
        }
        off += 64;
    }
    for (int k=0;k<4;k++){ acc[k].h[0]=h0[k]; acc[k].h[1]=h1[k]; acc[k].h[2]=h2[k]; acc[k].h[3]=h3[k]; acc[k].h[4]=h4[k]; }
}

/* Combine 4 stride accumulators (each holds sum of its blocks already * r^4 per step)
 * into one accumulator equal to processing all blocks sequentially with r.
 * acc[k] corresponds to blocks k, k+4, k+8, ... and has been multiplied by r^4 once per block.
 * The last block index for stream k is the most recent. To align powers:
 *   H = acc[0]*r^3 + acc[1]*r^2 + acc[2]*r + acc[3]   (mod p)
 * because acc[0]'s last block needs 3 more multiplications by r, etc.
 */
static void poly_combine4(const poly_key *pk, limb5 acc[4], uint32_t out[5]) {
    uint32_t h[5] = {0,0,0,0,0};
    for (int k = 0; k < 4; k++) {
        /* multiply acc[k] by r^(3-k) */
        uint32_t a[5]; memcpy(a, acc[k].h, sizeof a);
        for (int p = 0; p < 3-k; p++) poly_mul(a, pk->r, pk->r[1]*5, pk->r[2]*5, pk->r[3]*5, pk->r[4]*5);
        h[0]+=a[0]; h[1]+=a[1]; h[2]+=a[2]; h[3]+=a[3]; h[4]+=a[4];
    }
    /* carry */
    uint64_t c;
    c = h[0] >> 26; h[0] &= 0x3ffffff; h[1] += (uint32_t)c;
    c = h[1] >> 26; h[1] &= 0x3ffffff; h[2] += (uint32_t)c;
    c = h[2] >> 26; h[2] &= 0x3ffffff; h[3] += (uint32_t)c;
    c = h[3] >> 26; h[3] &= 0x3ffffff; h[4] += (uint32_t)c;
    c = h[4] >> 26; h[4] &= 0x3ffffff; h[0] += (uint32_t)c * 5;
    c = h[0] >> 26; h[0] &= 0x3ffffff; h[1] += (uint32_t)c;
    memcpy(out, h, sizeof h);
}

static void poly_finish(const poly_key *pk, uint32_t h0, uint32_t h1, uint32_t h2, uint32_t h3, uint32_t h4, uint8_t tag[16]) {
    uint32_t c = h1 >> 26; h1 &= 0x3ffffff; h2 += c;
    c = h2 >> 26; h2 &= 0x3ffffff; h3 += c;
    c = h3 >> 26; h3 &= 0x3ffffff; h4 += c;
    c = h4 >> 26; h4 &= 0x3ffffff; h0 += c * 5;
    c = h0 >> 26; h0 &= 0x3ffffff; h1 += c;
    uint32_t g0=h0+5; c=g0>>26; g0&=0x3ffffff;
    uint32_t g1=h1+c; c=g1>>26; g1&=0x3ffffff;
    uint32_t g2=h2+c; c=g2>>26; g2&=0x3ffffff;
    uint32_t g3=h3+c; c=g3>>26; g3&=0x3ffffff;
    uint32_t g4=h4+c-(1u<<26);
    uint32_t mask=(g4>>31)-1u;
    g0&=mask; g1&=mask; g2&=mask; g3&=mask; g4&=mask; mask=~mask;
    h0=(h0&mask)|g0; h1=(h1&mask)|g1; h2=(h2&mask)|g2; h3=(h3&mask)|g3; h4=(h4&mask)|g4;
    uint64_t f0=(h0 | ((uint64_t)h1<<26)) & 0xffffffff; f0 += pk->pad[0];
    uint64_t f1=(((uint64_t)h1>>6) | ((uint64_t)h2<<20)) & 0xffffffff; f1 += pk->pad[1] + (f0>>32);
    uint64_t f2=(((uint64_t)h2>>12) | ((uint64_t)h3<<14)) & 0xffffffff; f2 += pk->pad[2] + (f1>>32);
    uint64_t f3=(((uint64_t)h3>>18) | ((uint64_t)h4<<8)) & 0xffffffff; f3 += pk->pad[3] + (f2>>32);
    st32(tag+0,(uint32_t)f0); st32(tag+4,(uint32_t)f1); st32(tag+8,(uint32_t)f2); st32(tag+12,(uint32_t)f3);
}

/* ---------------- thread pool ---------------- */
typedef struct {
    const uint8_t *in; uint8_t *out;
    size_t off, len;       /* byte range within buffers; len multiple of 512 except tail thread */
    uint32_t counter;
    const poly_key *pk;
    limb5 acc[4];
    int do_poly;
} job_t;

static job_t jobs[NT];
static pthread_t threads[NT];
static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_work = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int work_gen = 0, done_count = 0, stop_flag = 0, pool_ready = 0;

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&mtx);
        while (work_gen == seen && !stop_flag) pthread_cond_wait(&cv_work, &mtx);
        if (stop_flag) { pthread_mutex_unlock(&mtx); break; }
        seen = work_gen;
        job_t j = jobs[id];
        pthread_mutex_unlock(&mtx);

        size_t off = 0;
        uint32_t counter = j.counter;
        while (off + 512 <= j.len) {
            chacha_xor8(counter, j.in + off, j.out + off);
            counter += 8; off += 512;
        }
        if (j.do_poly) {
            limb5 acc[4] = {{{0}},{{0}},{{0}},{{0}}};
            poly_blocks4(j.pk, j.out, off, acc);
            memcpy(j.acc, acc, sizeof acc);
        }
        pthread_mutex_lock(&mtx);
        if (j.do_poly) memcpy(jobs[id].acc, j.acc, sizeof j.acc);
        done_count++;
        if (done_count == NT) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mtx);
    }
    return NULL;
}

static void pool_init(void) {
    if (pool_ready) return;
    for (int i = 0; i < NT; i++) pthread_create(&threads[i], NULL, worker, (void*)(intptr_t)i);
    pool_ready = 1;
}

static void pool_run(void) {
    pthread_mutex_lock(&mtx);
    done_count = 0;
    work_gen++;
    pthread_cond_broadcast(&cv_work);
    while (done_count < NT) pthread_cond_wait(&cv_done, &mtx);
    pthread_mutex_unlock(&mtx);
}

/* scalar poly over arbitrary bytes (with AEAD zero-padding semantics: partial block
 * padded with zeros and treated as a full block, hibit 1). */
static void poly_update_bytes(uint32_t h[5], const poly_key *pk, const uint8_t *m, size_t n) {
    size_t off = 0;
    while (off + 16 <= n) { poly_block(h, m+off, 1, pk->r); off += 16; }
    if (off < n) {
        uint8_t tmp[16] = {0};
        memcpy(tmp, m+off, n-off);
        poly_block(h, tmp, 1, pk->r);
    }
}

/* ---------------- public entry ---------------- */
void chacha20poly1305_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                              const uint8_t *aad, size_t aad_len,
                              const uint8_t *pt, size_t pt_len,
                              uint8_t *ct, uint8_t tag[16]) {
    uint8_t block0[64];
    chacha_block(key, nonce, 0, block0);
    poly_key pk; poly_key_init(&pk, block0);

    uint32_t h[5] = {0,0,0,0,0};
    if (aad && aad_len) poly_update_bytes(h, &pk, aad, aad_len);

    chacha_init(key, nonce);

    if (pt_len >= 4096) {
        pool_init();
        size_t main = pt_len & ~511ULL;          /* multiple of 512 */
        size_t chunk = (main / NT) & ~511ULL;
        for (int i = 0; i < NT; i++) {
            size_t off = (size_t)i * chunk;
            size_t len = (i == NT-1) ? (main - off) : chunk;
            jobs[i].in = pt + off; jobs[i].out = ct + off;
            jobs[i].off = off; jobs[i].len = len;
            jobs[i].counter = (uint32_t)(1 + off/64);
            jobs[i].pk = &pk; jobs[i].do_poly = 1;
            memset(jobs[i].acc, 0, sizeof jobs[i].acc);
        }
        pool_run();

        /* combine per-thread accumulators. Thread i processed blocks starting at
         * global block index (off/16). Its combined accumulator represents the
         * product of its own blocks only; weight it by r^(blocks after it). */
        size_t total_blocks = main / 16;
        for (int i = NT-1; i >= 0; i--) {
            if (jobs[i].len == 0) continue;
            uint32_t part[5]; poly_combine4(&pk, jobs[i].acc, part);
            size_t blocks_after = total_blocks - (jobs[i].off + (jobs[i].len & ~63ULL))/16;
            /* multiply part by r^blocks_after */
            /* blocks_after can be large (~2.5M). Use square-and-multiply on r. */
            if (blocks_after) {
                /* compute r^blocks_after into pw, then part *= pw */
                uint32_t base[5]; memcpy(base, pk.r, sizeof base);
                uint32_t pw[5] = {1,0,0,0,0}; /* r^0 = 1 */
                size_t e = blocks_after;
                while (e) {
                    if (e & 1) poly_mul(pw, base, base[1]*5, base[2]*5, base[3]*5, base[4]*5);
                    uint32_t b2[5]; memcpy(b2, base, sizeof base);
                    poly_mul(base, b2, b2[1]*5, b2[2]*5, b2[3]*5, b2[4]*5);
                    e >>= 1;
                }
                poly_mul(part, pw, pw[1]*5, pw[2]*5, pw[3]*5, pw[4]*5);
            }
            h[0]+=part[0]; h[1]+=part[1]; h[2]+=part[2]; h[3]+=part[3]; h[4]+=part[4];
        }
        /* tail */
