{"command":"cat > poly_vec.c << 'EOF'
/* 2-way AVX2 Poly1305: two independent 26-bit-limb multiplications in the
 * low and high 128-bit lanes, processing 32 bytes per iteration (two blocks
 * of two separate accumulators? or one message two-at-a-time).
 * Here: single message, 2-way stride (blocks 0,2,4,... in lane0; 1,3,5,... in lane1),
 * each step multiplies by r^2. */
#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static inline uint32_t ld32(const uint8_t *p){uint32_t v; memcpy(&v,p,4); return v;}
static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

typedef struct {
    __m256i r0, r1, r2, r3, r4;   /* r^2 limbs broadcast in both 128-bit lanes (as 64-bit) */
    __m256i s1, s2, s3, s4;
    uint32_t r[5];
    uint32_t pad[4];
} pk_t;

static void mul_scalar(uint32_t h[5], const uint32_t r[5]) {
    uint32_t s1=r[1]*5, s2=r[2]*5, s3=r[3]*5, s4=r[4]*5;
    uint64_t d0=(uint64_t)h[0]*r[0]+(uint64_t)h[1]*s4+(uint64_t)h[2]*s3+(uint64_t)h[3]*s2+(uint64_t)h[4]*s1;
    uint64_t d1=(uint64_t)h[0]*r[1]+(uint64_t)h[1]*r[0]+(uint64_t)h[2]*s4+(uint64_t)h[3]*s3+(uint64_t)h[4]*s2;
    uint64_t d2=(uint64_t)h[0]*r[2]+(uint64_t)h[1]*r[1]+(uint64_t)h[2]*r[0]+(uint64_t)h[3]*s4+(uint64_t)h[4]*s3;
    uint64_t d3=(uint64_t)h[0]*r[3]+(uint64_t)h[1]*r[2]+(uint64_t)h[2]*r[1]+(uint64_t)h[3]*r[0]+(uint64_t)h[4]*s4;
    uint64_t d4=(uint64_t)h[0]*r[4]+(uint64_t)h[1]*r[3]+(uint64_t)h[2]*r[2]+(uint64_t)h[3]*r[1]+(uint64_t)h[4]*r[0];
    uint64_t c; c=d0>>26; h[0]=d0&0x3ffffff; d1+=c;
    c=d1>>26; h[1]=d1&0x3ffffff; d2+=c; c=d2>>26; h[2]=d2&0x3ffffff; d3+=c;
    c=d3>>26; h[3]=d3&0x3ffffff; d4+=c; c=d4>>26; h[4]=d4&0x3ffffff; h[0]+=(uint32_t)c*5;
    c=h[0]>>26; h[0]&=0x3ffffff; h[1]+=(uint32_t)c;
}

static void pk_init(pk_t *pk, const uint8_t key[32]) {
    uint32_t t0=ld32(key), t1=ld32(key+4), t2=ld32(key+8), t3=ld32(key+12);
    uint32_t r[5];
    r[0]=t0&0x3ffffff; r[1]=((t0>>26)|(t1<<6))&0x3ffff03;
    r[2]=((t1>>20)|(t2<<12))&0x3ffc0ff; r[3]=((t2>>14)|(t3<<18))&0x3f03fff; r[4]=(t3>>8)&0x00fffff;
    memcpy(pk->r, r, 20);
    uint32_t r2[5]; memcpy(r2, r, 20); mul_scalar(r2, r); /* r2 = r * r = r^2 */
    /* store each limb as 64-bit in both lanes */
    pk->r0=_mm256_set1_epi64x(r2[0]); pk->r1=_mm256_set1_epi64x(r2[1]);
    pk->r2=_mm256_set1_epi64x(r2[2]); pk->r3=_mm256_set1_epi64x(r2[3]); pk->r4=_mm256_set1_epi64x(r2[4]);
    pk->s1=_mm256_set1_epi64x((uint64_t)r2[1]*5); pk->s2=_mm256_set1_epi64x((uint64_t)r2[2]*5);
    pk->s3=_mm256_set1_epi64x((uint64_t)r2[3]*5); pk->s4=_mm256_set1_epi64x((uint64_t)r2[4]*5);
    pk->pad[0]=ld32(key+16); pk->pad[1]=ld32(key+20); pk->pad[2]=ld32(key+24); pk->pad[3]=ld32(key+28);
}

static inline __m256i add26(__m256i h, __m256i m) { return _mm256_add_epi64(h, m); }

/* process 32 bytes: block at m goes to lane0, block at m+16 to lane1, then multiply both by r^2 */
static inline void step(const pk_t *pk, __m256i *h0, __m256i *h1, __m256i *h2, __m256i *h3, __m256i *h4,
                        const uint8_t *m) {
    /* load two blocks and split into 26-bit limbs, placed in the two 64-bit lanes */
    uint32_t a0=ld32(m), a1=ld32(m+4), a2=ld32(m+8), a3=ld32(m+12);
    uint32_t b0=ld32(m+16), b1=ld32(m+20), b2=ld32(m+24), b3=ld32(m+28);
