/* ---------------- thread pool ---------------- */
typedef struct { const uint8_t *in; uint8_t *out; size_t len; uint32_t counter; } job_t;
static job_t jobs[NT];
static pthread_t threads[NT];
static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_work = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int work_gen = 0, done_count = 0, stop_flag = 0, pool_ready = 0;

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg, seen = 0;
    for (;;) {
        pthread_mutex_lock(&mtx);
        while (work_gen == seen && !stop_flag) pthread_cond_wait(&cv_work, &mtx);
        if (stop_flag) { pthread_mutex_unlock(&mtx); break; }
        seen = work_gen;
        job_t j = jobs[id];
        pthread_mutex_unlock(&mtx);
        uint32_t counter = j.counter;
        size_t off = 0;
        while (off + 512 <= j.len) {
            chacha_xor8(counter, j.in + off, j.out + off);
            counter += 8; off += 512;
        }
        pthread_mutex_lock(&mtx);
        done_count++;
        if (done_count == NT) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mtx);
    }
    return NULL;
}

static void pool_init(void) {
    if (pool_ready) return;
    for (int i = 0; i < NT; i++) pthread_create(&threads[i], NULL, worker, (void*)(intptr_t)i);
    pool_ready = 1;
}

static void pool_run(void) {
    pthread_mutex_lock(&mtx);
    done_count = 0; work_gen++;
    pthread_cond_broadcast(&cv_work);
    while (done_count < NT) pthread_cond_wait(&cv_done, &mtx);
    pthread_mutex_unlock(&mtx);
}

/* ---------------- Poly1305 via OpenSSL ---------------- */
static EVP_MAC *MAC = NULL;
static EVP_MAC_CTX *MAC_CTX = NULL;

static void mac_init(void) {
    if (MAC) return;
    MAC = EVP_MAC_fetch(NULL, "POLY1305", NULL);
    MAC_CTX = EVP_MAC_CTX_new(MAC);
}

static void poly1305_tag(const uint8_t key[32], const uint8_t *aad, size_t aad_len,
                         const uint8_t *ct, size_t ct_len, uint8_t tag[16]) {
    mac_init();
    EVP_MAC_init(MAC_CTX, key, 32, NULL);
    if (aad_len) {
        size_t full = aad_len & ~15ULL;
        if (full) EVP_MAC_update(MAC_CTX, aad, full);
        if (aad_len & 15) {
            uint8_t tmp[16] = {0};
            memcpy(tmp, aad + full, aad_len & 15);
            EVP_MAC_update(MAC_CTX, tmp, 16);
        }
    }
    if (ct_len) {
        size_t full = ct_len & ~15ULL;
        if (full) EVP_MAC_update(MAC_CTX, ct, full);
        if (ct_len & 15) {
            uint8_t tmp[16] = {0};
            memcpy(tmp, ct + full, ct_len & 15);
            EVP_MAC_update(MAC_CTX, tmp, 16);
        }
    }
    uint8_t lens[16];
    uint64_t al = aad_len, cl = ct_len;
    memcpy(lens, &al, 8); memcpy(lens+8, &cl, 8);
    EVP_MAC_update(MAC_CTX, lens, 16);
    size_t outl = 16;
    EVP_MAC_final(MAC_CTX, tag, &outl, 16);
}

void chacha20poly1305_encrypt(const uint8_t key[32], const uint8_t nonce[12],
                              const uint8_t *aad, size_t aad_len,
                              const uint8_t *pt, size_t pt_len,
                              uint8_t *ct, uint8_t tag[16]) {
    /* poly1305 one-time key = ChaCha20 block 0 */
    uint8_t block0[64];
    chacha_block(key, nonce, 0, block0);

    chacha_init(key, nonce);

    if (pt_len >= 1024) {
        pool_init();
        size_t main = pt_len & ~511ULL;
        size_t chunk = (main / NT) & ~511ULL;
        if (chunk == 0) {
            /* too small to split: one thread */
            for (int i = 0; i < NT; i++) { jobs[i].in = pt; jobs[i].out = ct; jobs[i].len = (i==0)?main:0; jobs[i].counter = 1; }
        } else {
            for (int i = 0; i < NT; i++) {
                size_t off = (size_t)i * chunk;
                size_t len = (i == NT-1) ? (main - off) : chunk;
                jobs[i].in = pt + off; jobs[i].out = ct + off;
                jobs[i].len = len; jobs[i].counter = (uint32_t)(1 + off/64);
            }
        }
        pool_run();
        if (main < pt_len) {
            size_t rem = pt_len - main;
            uint8_t ks[512];
            uint32_t counter = (uint32_t)(1 + main/64);
            size_t gen = 0;
            while (gen < rem) { chacha_block(key, nonce, counter++, ks + gen); gen += 64; }
            for (size_t i = 0; i < rem; i++) ct[main+i] = pt[main+i] ^ ks[i];
        }
    } else {
        size_t off = 0;
        while (off + 512 <= pt_len) { chacha_xor8((uint32_t)(1+off/64), pt+off, ct+off); off += 512; }
        if (off < pt_len) {
            size_t rem = pt_len - off;
            uint8_t ks[512];
            uint32_t counter = (uint32_t)(1+off/64);
            size_t gen = 0;
            while (gen < rem) { chacha_block(key, nonce, counter++, ks+gen); gen += 64; }
            for (size_t i = 0; i < rem; i++) ct[off+i] = pt[off+i] ^ ks[i];
        }
    }

    poly1305_tag(block0, aad, aad_len, ct, pt_len, tag);
