/* 128-bit-limb Poly1305 with fast exponentiation, verified against OpenSSL. */
#include <openssl/evp.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef unsigned __int128 u128;
static inline uint32_t ld32(const uint8_t *p){uint32_t v; memcpy(&v,p,4); return v;}

/* value = lo + top*2^128, top small */
typedef struct { u128 lo; uint32_t top; } num;

static num nreduce(num a){
    /* fold top: top*2^128 = (top>>2)*2^130 + (top&3)*2^128 ≡ (top>>2)*5 + (top&3)*2^128 */
    for (int i = 0; i < 3 && a.top >= 4; i++) {
        u128 add = (u128)(a.top >> 2) * 5;
        u128 nlo = a.lo + add;
        uint32_t carry = nlo < a.lo;
        a.lo = nlo;
        a.top = (a.top & 3) + carry;
    }
    return a;
}

static num nadd(num a, num b){
    u128 s = a.lo + b.lo;
    num r = {s, a.top + b.top + (s < a.lo)};
    return nreduce(r);
}

static num nfrom_block(const uint8_t m[16], int hibit){
    uint64_t m0, m1; memcpy(&m0, m, 8); memcpy(&m1, m+8, 8);
    num r = {((u128)m1 << 64) | m0, hibit ? 1u : 0u};
    return r;
}

/* (lo + top*2^128) * r, r is 128-bit clamped key */
static num nmul(num a, u128 r){
    a = nreduce(a);
