    u128 tr = (u128)a.top * r;          /* fits: top<=3 after reduce, r<2^128 -> < 2^130, may be 131 bits */
    /* tr fits in 131 bits. Represent as tr_lo (128) + tr_top*2^128 where tr_top = a.top * r >> 128. */
    u128 tr_lo = tr; /* truncation! need full product a.top * r */
    /* compute a.top * r fully: a.top is small, so high part = (a.top * r) >> 128 */
    u128 tr_full_hi = 0;
