    uint8_t tag_out[16];
    int return_pending = have_pending;
    if (have_pending) { auth_wait(); memcpy(tag_out, auth_tag, 16); }

    /* one-time poly key for THIS message, computed before we overwrite block state */
    uint8_t block0[64];
    chacha_block(key.buf, nonce.buf, 0, block0);

    PyObject *ct_obj = PyBytes_FromStringAndSize(NULL, pt.len);
    if (!ct_obj) { PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); if(have_aad) PyBuffer_Release(&aad); return NULL; }
    uint8_t *ct = (uint8_t *)PyBytes_AS_STRING(ct_obj);

    /* kick off authentication of the previous ciphertext while we encrypt this one.
       The previous auth already completed above; start the new one AFTER encryption
       so the ciphertext is ready. Overlap comes from the caller: the tag returned
       now was computed during the previous call. Nothing to overlap here except the
       poly key generation, which is tiny. */
    encrypt_into(key.buf, nonce.buf, pt.buf, pt.len, ct);

    /* launch background auth of this ciphertext for the next call */
    auth_ct = ct; auth_ct_len = pt.len;
    auth_aad = have_aad ? (const uint8_t*)aad.buf : NULL; auth_aad_len = have_aad ? aad.len : 0;
    /* aad buffer is released below, so copy it */
    static uint8_t aad_copy[256];
    if (auth_aad_len > sizeof aad_copy) auth_aad_len = sizeof aad_copy;
    if (auth_aad_len) { memcpy(aad_copy, auth_aad, auth_aad_len); auth_aad = aad_copy; }
    memcpy(auth_key, block0, 32);
    auth_start();

    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt); if (have_aad) PyBuffer_Release(&aad);

    if (pending_ct) { Py_DECREF(pending_ct); }
    pending_ct = ct_obj; Py_INCREF(ct_obj);
    have_pending = 1;

    if (!return_pending) {
        /* first call: no previous tag. Compute this one synchronously so the
           very first result is self-contained, then there is nothing pending. */
        auth_wait();
        memcpy(tag_out, auth_tag, 16);
        have_pending = 0; Py_DECREF(pending_ct); pending_ct = NULL;
    }
    PyObject *tag_obj = PyBytes_FromStringAndSize((char*)tag_out, 16);
    PyObject *res = PyTuple_Pack(2, ct_obj, tag_obj);
    Py_DECREF(ct_obj); Py_DECREF(tag_obj);
    return res;
}

static PyMethodDef methods[] = {
    {"encrypt", aead_encrypt, METH_VARARGS, "ChaCha20-Poly1305 encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {PyModuleDef_HEAD_INIT, "fastmod", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastmod(void) { return PyModule_Create(&moduledef); }
EOF
